internal enum class AppSystemBackAction {
    RETURN_TO_HOME_TAB,
    NAVIGATE_UP,
    FINISH_ACTIVITY
}

internal fun resolveAppSystemBackAction(
    isAtMainHostRoot: Boolean,
    currentBottomItem: BottomNavItem,
    homeItem: BottomNavItem = BottomNavItem.HOME
): AppSystemBackAction {
    if (!isAtMainHostRoot) {
        return AppSystemBackAction.NAVIGATE_UP
    }
    if (currentBottomItem != homeItem) {
        return AppSystemBackAction.RETURN_TO_HOME_TAB
    }
    return AppSystemBackAction.FINISH_ACTIVITY
}

internal fun shouldInterceptSystemBackForAppAction(
    action: AppSystemBackAction
): Boolean {
    return action == AppSystemBackAction.RETURN_TO_HOME_TAB
}

internal fun resolveSettingsNavPopTransition(
    fromRoute: String?,
    toRoute: String?,
    activeMainHostRoute: String? = null,
): BiliPaiNavRouteTransition? {
    if (!isSettingsSubtreeRoute(fromRoute)) return null
    val normalizedTo = toRoute?.substringBefore("?")?.takeIf { it.isNotBlank() } ?: return null
    val normalizedActive = activeMainHostRoute?.substringBefore("?")?.takeIf { it.isNotBlank() }
    // 只要底栏有活跃 tab，pop 回 MainHost 时就以该 tab 作为设置树的“父级”，
    // 使首页/动态/我的等任意入口打开设置根页后都能命中设置树 iOS pop 动画。
    val effectiveParentRoute = if (
        normalizedTo == BiliPaiNavKey.MainHost.routeBase &&
        normalizedActive != null
    ) {
        normalizedActive
    } else {
        normalizedTo
    }
    if (isSettingsNavHierarchyTransition(
            parentRoute = effectiveParentRoute,
            childRoute = fromRoute,
        )
    ) {
        return BiliPaiNavRouteTransition.SETTINGS_IOS_PUSH_POP
    }
    // 设置子树任意页直接回到 MainHost，且底栏仍在 Settings：统一走设置 iOS pop，
    // 覆盖非严格父子边（如搜索直达 animation 后一键返回）。
    if (normalizedTo == BiliPaiNavKey.MainHost.routeBase && isSettingsSubtreeRoute(normalizedActive)) {
        return BiliPaiNavRouteTransition.SETTINGS_IOS_PUSH_POP
    }
    return null
}

internal fun resolveSettingsNavPopTransition(
    fromKey: BiliPaiNavKey?,
    toKey: BiliPaiNavKey?,
    activeMainHostRoute: String? = null,
): BiliPaiNavRouteTransition? {
    if (fromKey == null || toKey == null) return null
    return resolveSettingsNavPopTransition(
        fromRoute = fromKey.routeBase,
        toRoute = toKey.routeBase,
        activeMainHostRoute = activeMainHostRoute,
    )
}

internal fun isSettingsNavPopTransition(
    fromKey: BiliPaiNavKey?,
    toKey: BiliPaiNavKey?,
    activeMainHostRoute: String? = null,
): Boolean {
    return resolveSettingsNavPopTransition(
        fromKey = fromKey,
        toKey = toKey,
        activeMainHostRoute = activeMainHostRoute,
    ) != null
}

@Composable
internal fun VideoCardTransitionHostDepthLayer(
    enabled: Boolean,
    snapshotHandle: VideoCardTransitionSnapshotHandle,
    progressProvider: () -> Float,
    phaseProvider: () -> VideoCardTransitionBackgroundPhase,
    exposureProvider: () -> VideoCardTransitionExposure,
    isGestureRestoreInProgressProvider: () -> Boolean = { false },
    motionTierProvider: () -> MotionTier = { MotionTier.Normal },
    isLightBackgroundProvider: () -> Boolean = { false },
    realtimeBlurEnabledProvider: () -> Boolean = { false },
    scaleReductionProvider: () -> Float = { VIDEO_CARD_TRANSITION_BACKGROUND_SCALE_REDUCTION },
    sourceBoundsProvider: () -> Rect? = { null },
    modifier: Modifier = Modifier,
) {
    val contentLayer = snapshotHandle.contentLayer
    val snapshotState = snapshotHandle.state
    if (!enabled) {
        SideEffect { snapshotHandle.clearRenderEffect() }
        return
    }
    val view = LocalView.current
    var deviceCornerRadiusPx by remember { mutableFloatStateOf(0f) }
    SideEffect {
        deviceCornerRadiusPx = resolveDeviceDisplayCornerRadiusPx(view.rootWindowInsets)
        if (!realtimeBlurEnabledProvider()) snapshotHandle.clearRenderEffect()
    }
    Box(
        modifier = modifier
            .fillMaxSize()
            .drawWithContent {
                // Host 层无子内容；只绘制冻结快照。
                val exposure = exposureProvider()
                val motionTier = motionTierProvider()
                val realtimeBlur = realtimeBlurEnabledProvider()
                if (
                    !shouldPaintHostOwnedDepthLayer(
                        exposure = exposure,
                        hasRecordedContent = snapshotState.hasRecordedContent,
                        displayListStale = snapshotState.displayListStale,
                        motionTier = motionTier,
                        realtimeBlurEnabled = realtimeBlur,
                    )
                ) {
                    return@drawWithContent
                }
                val phase = phaseProvider()
                // SettledHidden：详情盖住时仍保持满糊，手势首帧无「先清晰再糊」跳变。
                val progress = resolveHostOwnedDepthProgress(
                    exposure = exposure,
                    liveProgress = progressProvider(),
                )
                val frame = snapshotState.frameCache.resolve(
                    progress = progress,
                    phase = phase,
                    motionTier = motionTier,
                    isLightBackground = isLightBackgroundProvider(),
                    isGestureRestoreInProgress = isGestureRestoreInProgressProvider(),
                    density = density,
                    deviceCornerRadiusPx = deviceCornerRadiusPx,
                    scaleReduction = scaleReductionProvider(),
                )
                applyVideoCardTransitionSnapshotFrame(
                    contentLayer = contentLayer,
                    snapshotState = snapshotState,
                    frame = frame,
                    canvasSize = size,
                    sourceBounds = sourceBoundsProvider(),
                )
                if (shouldDrawVideoCardTransitionScaleGapFill(frame.contentScale)) {
                    drawRect(
                        resolveVideoCardTransitionScaleGapFillColor(
                            isLightBackground = frame.useLightScrimTint,
                            scrimAlpha = frame.scrimAlpha,
                        )
                    )
                }
                val frozenLayerAlpha = resolveVideoCardTransitionFrozenLayerAlpha(
                    exposure = exposure,
                    depthProgress = progress,
                )
                contentLayer.alpha = frozenLayerAlpha
                if (frozenLayerAlpha > 0.001f) {
                    drawLayer(contentLayer)
                    VideoCardTransitionDiagnostics.onSourceLayerDrawn()
                }
                if (frame.scrimAlpha > 0.001f) {
                    val scrimColor = if (frame.useLightScrimTint) {
                        VIDEO_CARD_TRANSITION_LIGHT_SCRIM_TINT
                    } else {
                        Color.Black
                    }
                    drawRect(scrimColor.copy(alpha = frame.scrimAlpha))
                }
            },
    )
}

/**
 * Host 层何时绘制：有**可用**冻结内容时。
 *
 * - stale / 无内容：永不 paint（防黑屏）。
 * - [SettledHidden]：详情下预热满糊。
 * - [BackPreview]/[Returning]/[Restoring]：drawable 时垫跟手/消糊景深；
 *   源 dispose 后 DL 失效时 stale=true，Host 不画，等源重录。
 */

internal fun shouldPaintHostOwnedDepthLayer(
    exposure: VideoCardTransitionExposure,
    hasRecordedContent: Boolean,
    displayListStale: Boolean = false,
    motionTier: MotionTier,
    realtimeBlurEnabled: Boolean,
    sdkInt: Int = Build.VERSION.SDK_INT,
): Boolean {
    if (
        !isVideoCardTransitionSnapshotDrawable(
            hasRecordedContent = hasRecordedContent,
            displayListStale = displayListStale,
        )
    ) {
        return false
    }
    if (motionTier == MotionTier.Reduced) return false
    if (!realtimeBlurEnabled) return false
    if (sdkInt < Build.VERSION_CODES.S) return false
    return when (exposure) {
        // SettledHidden：详情下预热（须 drawable）。
        // BackPreview/Returning：drawable 时 Host 在 NavDisplay 下垫一层跟手糊；
        // 源页重录后会在其上画同 layer。stale 时 Host 不画（防黑），源 live/重录接手。
        VideoCardTransitionExposure.SettledHidden,
        VideoCardTransitionExposure.BackPreview,
        VideoCardTransitionExposure.Restoring,
        VideoCardTransitionExposure.Returning,
        -> true
        VideoCardTransitionExposure.Opening,
        VideoCardTransitionExposure.Idle,
        -> false
    }
}

/** SettledHidden 强制满糊；其余跟 live progress（含预测手势 1→0）。 */

internal fun resolveHostOwnedDepthProgress(
    exposure: VideoCardTransitionExposure,
    liveProgress: Float,
): Float {
    return when (exposure) {
        VideoCardTransitionExposure.SettledHidden -> 1f
        else -> liveProgress.coerceIn(0f, 1f)
    }
}

/**
 * 来源 Scene 的 DisposableEffect 是否可销毁 Host 快照。
 * Host 共享 handle 时禁止 dispose 清层，否则预测返回无糊可用。
 */

internal fun shouldMarkDisplayListStaleOnHostOwnedSourceDispose(): Boolean = false

/**
 * 仅 IDLE 才释放 Host 快照 / BlurEffect；SettledHidden 必须保留满糊层。
 */

internal fun shouldReleaseHostOwnedDepthLayer(
    exposure: VideoCardTransitionExposure,
): Boolean = exposure == VideoCardTransitionExposure.Idle

internal const val PREDICTIVE_BACK_BACKGROUND_COMMIT_DURATION_MS = 200

internal const val PREDICTIVE_BACK_BACKGROUND_CANCEL_DURATION_MS = 160

internal data class PredictiveBackBackgroundState(
    val progressProvider: () -> Float = { 0f },
    val targetKeyProvider: () -> BiliPaiNavKey? = { null },
    val motionTierProvider: () -> MotionTier = { MotionTier.Normal },
    val isLightBackgroundProvider: () -> Boolean = { false },
)

internal val LocalPredictiveBackBackgroundState = compositionLocalOf {
    PredictiveBackBackgroundState()
}

/**
 * 预测式返回手势进行中，把系统回退进度(0→1)映射为底层页模糊强度。
 *
 * 统一为随手势减弱(1→0)：底层页随返回露出来应逐渐清晰。
 * （旧版 CLASSIC_CARD 等用 0→1 增强模糊，体感与设置页相反，已统一。）
 */

internal fun resolvePredictiveBackGestureBlurProgress(
    backProgress: Float,
    routeTransition: BiliPaiNavRouteTransition? = null,
): Float {
    @Suppress("UNUSED_PARAMETER")
    val ignoredTransition = routeTransition
    val clamped = backProgress.coerceIn(0f, 1f)
    // 1:1 跟手线性渐变：手指拖出多少比例，底层模糊就线性退去多少；反向推回则等比恢复，手感丝滑连贯。
    return 1f - clamped
}

internal fun shouldApplyPredictiveBackGestureBlur(
    routeTransition: BiliPaiNavRouteTransition,
    predictiveBackEnabled: Boolean,
    gestureReturningVideoCard: Boolean,
    motionTier: MotionTier,
): Boolean {
    if (!predictiveBackEnabled) return false
    if (gestureReturningVideoCard) return false
    if (motionTier == MotionTier.Reduced) return false
    if (routeTransition == BiliPaiNavRouteTransition.NO_OP_SHARED_ELEMENT) return false
    // 设置 iOS 预测返回已靠横滑露出完整底层页；再叠满屏 GPU 模糊会起手发灰、跟手发沉。
    if (routeTransition == BiliPaiNavRouteTransition.SETTINGS_IOS_PUSH_POP) return false
    return routeTransition == BiliPaiNavRouteTransition.CLASSIC_CARD ||
        routeTransition == BiliPaiNavRouteTransition.BOTTOM_BAR_SIBLING_POP ||
        routeTransition == BiliPaiNavRouteTransition.LIGHT_SIBLING_POP
}

internal fun shouldApplyPredictiveBackBlurToRoute(
    entryKey: BiliPaiNavKey,
    targetBackKey: BiliPaiNavKey?,
    videoCardBackgroundApplied: Boolean = false,
): Boolean {
    return !videoCardBackgroundApplied && targetBackKey != null && entryKey == targetBackKey
}

internal fun resolvePredictiveBackCommitBlurDurationMs(startProgress: Float): Int {
    val clamped = startProgress.coerceIn(0f, 1f)
    if (clamped <= 0f) {
        return PREDICTIVE_BACK_BACKGROUND_CANCEL_DURATION_MS
    }
    return (PREDICTIVE_BACK_BACKGROUND_COMMIT_DURATION_MS * clamped)
        .roundToInt()
        .coerceIn(1, PREDICTIVE_BACK_BACKGROUND_COMMIT_DURATION_MS)
}

private class PredictiveBackBlurFrameCache {
    private var lastProgress = Float.NaN
    private var lastMotionTier: MotionTier? = null
    private var lastIsLightBackground: Boolean? = null
    private var cached = PredictiveBackBlurFrame(blurRadiusPx = 0f)

    fun resolve(
        progress: Float,
        motionTier: MotionTier,
        isLightBackground: Boolean,
    ): PredictiveBackBlurFrame {
        if (
            progress != lastProgress ||
            motionTier != lastMotionTier ||
            isLightBackground != lastIsLightBackground
        ) {
            lastProgress = progress
            lastMotionTier = motionTier
            lastIsLightBackground = isLightBackground
            cached = resolvePredictiveBackBlurFrame(
                progress = progress,
                motionTier = motionTier,
                isLightBackground = isLightBackground,
            )
        }
        return cached
    }
}

internal fun Modifier.predictiveBackBackgroundEffect(
    progressProvider: () -> Float,
    motionTierProvider: () -> MotionTier = { MotionTier.Normal },
    isLightBackgroundProvider: () -> Boolean = { false },
): Modifier {
    val frameCache = PredictiveBackBlurFrameCache()
    return graphicsLayer {
        val frame = frameCache.resolve(
            progressProvider(),
            motionTierProvider(),
            isLightBackgroundProvider(),
        )
        renderEffect = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && frame.blurRadiusPx > 0.01f) {
            RenderEffect
                .createBlurEffect(
                    frame.blurRadiusPx,
                    frame.blurRadiusPx,
                    Shader.TileMode.CLAMP,
                )
                .asComposeRenderEffect()
        } else {
            null
        }
    }.drawWithContent {
        drawContent()
        val frame = frameCache.resolve(
            progressProvider(),
            motionTierProvider(),
            isLightBackgroundProvider(),
        )
        if (frame.separationTintAlpha > 0.001f) {
            val tintColor = if (frame.useLightSeparationTint) Color.White else Color.Black
            drawRect(tintColor.copy(alpha = frame.separationTintAlpha))
        }
    }
}

